import{_ as e,c as a,o,a0 as t}from"./chunks/framework.DKRgXLPU.js";const l=JSON.parse('{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance.","frontmatter":{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance."},"headers":[],"relativePath":"en/blog/elite-goal-setting.md","filePath":"en/blog/elite-goal-setting.md"}');const i=e({name:"en/blog/elite-goal-setting.md"},[["render",function(e,l,i,r,n,s){return o(),a("div",null,[...l[0]||(l[0]=[t('<h1 id="goal-setting-for-elite-athletes" tabindex="-1">Goal Setting for Elite Athletes <a class="header-anchor" href="#goal-setting-for-elite-athletes" aria-label="Permalink to &quot;Goal Setting for Elite Athletes&quot;">​</a></h1><p>Goal setting seems simple: decide what you want, work toward it. But elite-level goal setting is more nuanced. The right goals accelerate development; the wrong ones create frustration and stagnation.</p><h2 id="beyond-basic-goals" tabindex="-1">Beyond Basic Goals <a class="header-anchor" href="#beyond-basic-goals" aria-label="Permalink to &quot;Beyond Basic Goals&quot;">​</a></h2><p>Most players set outcome goals: &quot;Win the regional championship.&quot; These goals have problems:</p><ul><li>You can&#39;t fully control outcomes</li><li>They create pressure without direction</li><li>Success or failure is binary</li><li>They don&#39;t guide daily practice</li></ul><p>Elite goal setting goes deeper.</p><h2 id="the-goal-hierarchy" tabindex="-1">The Goal Hierarchy <a class="header-anchor" href="#the-goal-hierarchy" aria-label="Permalink to &quot;The Goal Hierarchy&quot;">​</a></h2><h3 id="level-1-dream-goals-1-5-years" tabindex="-1">Level 1: Dream Goals (1-5 years) <a class="header-anchor" href="#level-1-dream-goals-1-5-years" aria-label="Permalink to &quot;Level 1: Dream Goals (1-5 years)&quot;">​</a></h3><p>Your ultimate aspirations:</p><ul><li>&quot;Compete at national level&quot;</li><li>&quot;Be recognized as an elite shooter&quot;</li><li>&quot;Win a major championship&quot;</li></ul><p>These provide direction and motivation but aren&#39;t actionable daily.</p><h3 id="level-2-performance-goals-season-year" tabindex="-1">Level 2: Performance Goals (Season/Year) <a class="header-anchor" href="#level-2-performance-goals-season-year" aria-label="Permalink to &quot;Level 2: Performance Goals (Season/Year)&quot;">​</a></h3><p>Measurable improvements in your game:</p><ul><li>&quot;Increase shooting accuracy from 60% to 70%&quot;</li><li>&quot;Reduce unforced errors by 25%&quot;</li><li>&quot;Develop a reliable plombée&quot;</li></ul><p>These are within your control and measurable.</p><h3 id="level-3-process-goals-daily-weekly" tabindex="-1">Level 3: Process Goals (Daily/Weekly) <a class="header-anchor" href="#level-3-process-goals-daily-weekly" aria-label="Permalink to &quot;Level 3: Process Goals (Daily/Weekly)&quot;">​</a></h3><p>The actions that drive improvement:</p><ul><li>&quot;Complete pre-shot routine on every throw&quot;</li><li>&quot;Practice visualization for 10 minutes daily&quot;</li><li>&quot;Train shooting technique 3x per week&quot;</li></ul><p>These are fully controllable and build toward performance goals.</p><h2 id="the-smart-framework" tabindex="-1">The SMART+ Framework <a class="header-anchor" href="#the-smart-framework" aria-label="Permalink to &quot;The SMART+ Framework&quot;">​</a></h2><p>Go beyond basic SMART goals:</p><h3 id="specific" tabindex="-1">Specific <a class="header-anchor" href="#specific" aria-label="Permalink to &quot;Specific&quot;">​</a></h3><p>Not &quot;improve my pointing&quot; but &quot;develop a consistent demi-portée that lands within 30cm of target from 8 meters.&quot;</p><h3 id="measurable" tabindex="-1">Measurable <a class="header-anchor" href="#measurable" aria-label="Permalink to &quot;Measurable&quot;">​</a></h3><p>Define how you&#39;ll track progress:</p><ul><li>Success rate percentages</li><li>Consistency metrics</li><li>Video analysis markers</li></ul><h3 id="achievable-but-stretching" tabindex="-1">Achievable but Stretching <a class="header-anchor" href="#achievable-but-stretching" aria-label="Permalink to &quot;Achievable but Stretching&quot;">​</a></h3><p>The goal should require growth but be realistic. A 60% shooter aiming for 65% is achievable; aiming for 90% is fantasy.</p><h3 id="relevant" tabindex="-1">Relevant <a class="header-anchor" href="#relevant" aria-label="Permalink to &quot;Relevant&quot;">​</a></h3><p>Goals must connect to your larger aspirations and address actual weaknesses, not just what&#39;s easy to improve.</p><h3 id="time-bound" tabindex="-1">Time-bound <a class="header-anchor" href="#time-bound" aria-label="Permalink to &quot;Time-bound&quot;">​</a></h3><p>Set clear deadlines:</p><ul><li>&quot;By end of season&quot;</li><li>&quot;Within 3 months&quot;</li><li>&quot;By the national championship&quot;</li></ul><h3 id="personally-meaningful" tabindex="-1">+ Personally Meaningful <a class="header-anchor" href="#personally-meaningful" aria-label="Permalink to &quot;+ Personally Meaningful&quot;">​</a></h3><p>The goal must matter to YOU, not just your coach or teammates. Internal motivation sustains effort when progress is slow.</p><h2 id="process-vs-outcome-focus" tabindex="-1">Process vs. Outcome Focus <a class="header-anchor" href="#process-vs-outcome-focus" aria-label="Permalink to &quot;Process vs. Outcome Focus&quot;">​</a></h2><h3 id="the-problem-with-outcome-goals" tabindex="-1">The Problem with Outcome Goals <a class="header-anchor" href="#the-problem-with-outcome-goals" aria-label="Permalink to &quot;The Problem with Outcome Goals&quot;">​</a></h3><p>&quot;Win the match&quot; creates problems:</p><ul><li>Anxiety about things you can&#39;t control</li><li>Distraction from execution</li><li>All-or-nothing thinking</li><li>Pressure without guidance</li></ul><h3 id="the-power-of-process-goals" tabindex="-1">The Power of Process Goals <a class="header-anchor" href="#the-power-of-process-goals" aria-label="Permalink to &quot;The Power of Process Goals&quot;">​</a></h3><p>&quot;Execute my pre-shot routine perfectly&quot; offers:</p><ul><li>Full control</li><li>Clear focus</li><li>Immediate feedback</li><li>Builds toward outcomes naturally</li></ul><h3 id="the-balance" tabindex="-1">The Balance <a class="header-anchor" href="#the-balance" aria-label="Permalink to &quot;The Balance&quot;">​</a></h3><p>Use outcome goals for motivation and direction. Use process goals for daily focus and execution.</p><h2 id="goal-setting-for-different-phases" tabindex="-1">Goal Setting for Different Phases <a class="header-anchor" href="#goal-setting-for-different-phases" aria-label="Permalink to &quot;Goal Setting for Different Phases&quot;">​</a></h2><h3 id="off-season" tabindex="-1">Off-Season <a class="header-anchor" href="#off-season" aria-label="Permalink to &quot;Off-Season&quot;">​</a></h3><p>Focus on development goals:</p><ul><li>Technical improvements</li><li>Physical conditioning</li><li>Mental skill building</li><li>Expanding your palette of throws</li></ul><h3 id="pre-season" tabindex="-1">Pre-Season <a class="header-anchor" href="#pre-season" aria-label="Permalink to &quot;Pre-Season&quot;">​</a></h3><p>Transition to integration:</p><ul><li>Combining skills in match-like conditions</li><li>Testing improvements in friendly competition</li><li>Refining strategies</li></ul><h3 id="competition-season" tabindex="-1">Competition Season <a class="header-anchor" href="#competition-season" aria-label="Permalink to &quot;Competition Season&quot;">​</a></h3><p>Shift to performance and process:</p><ul><li>Executing what you&#39;ve developed</li><li>Process goals for each match</li><li>Minimal technical changes</li></ul><h3 id="post-competition" tabindex="-1">Post-Competition <a class="header-anchor" href="#post-competition" aria-label="Permalink to &quot;Post-Competition&quot;">​</a></h3><p>Reflection and planning:</p><ul><li>Analyze what worked</li><li>Identify areas for growth</li><li>Set goals for next cycle</li></ul><h2 id="common-goal-setting-mistakes" tabindex="-1">Common Goal-Setting Mistakes <a class="header-anchor" href="#common-goal-setting-mistakes" aria-label="Permalink to &quot;Common Goal-Setting Mistakes&quot;">​</a></h2><h3 id="too-many-goals" tabindex="-1">Too Many Goals <a class="header-anchor" href="#too-many-goals" aria-label="Permalink to &quot;Too Many Goals&quot;">​</a></h3><p>Focus is power. 2-3 key goals beat 10 scattered ones.</p><h3 id="only-outcome-goals" tabindex="-1">Only Outcome Goals <a class="header-anchor" href="#only-outcome-goals" aria-label="Permalink to &quot;Only Outcome Goals&quot;">​</a></h3><p>Without process goals, you have no roadmap.</p><h3 id="no-flexibility" tabindex="-1">No Flexibility <a class="header-anchor" href="#no-flexibility" aria-label="Permalink to &quot;No Flexibility&quot;">​</a></h3><p>Goals should adapt to new information. Rigid adherence to outdated goals wastes effort.</p><h3 id="comparison-based-goals" tabindex="-1">Comparison-Based Goals <a class="header-anchor" href="#comparison-based-goals" aria-label="Permalink to &quot;Comparison-Based Goals&quot;">​</a></h3><p>&quot;Be better than [player]&quot; puts your success in someone else&#39;s hands.</p><h3 id="neglecting-mental-goals" tabindex="-1">Neglecting Mental Goals <a class="header-anchor" href="#neglecting-mental-goals" aria-label="Permalink to &quot;Neglecting Mental Goals&quot;">​</a></h3><p>Technical and physical goals dominate, but mental skills often determine who wins.</p><h2 id="implementation-strategies" tabindex="-1">Implementation Strategies <a class="header-anchor" href="#implementation-strategies" aria-label="Permalink to &quot;Implementation Strategies&quot;">​</a></h2><h3 id="write-them-down" tabindex="-1">Write Them Down <a class="header-anchor" href="#write-them-down" aria-label="Permalink to &quot;Write Them Down&quot;">​</a></h3><p>Written goals are significantly more likely to be achieved.</p><h3 id="review-regularly" tabindex="-1">Review Regularly <a class="header-anchor" href="#review-regularly" aria-label="Permalink to &quot;Review Regularly&quot;">​</a></h3><p>Weekly review keeps goals present and allows adjustment.</p><h3 id="share-selectively" tabindex="-1">Share Selectively <a class="header-anchor" href="#share-selectively" aria-label="Permalink to &quot;Share Selectively&quot;">​</a></h3><p>Share with those who will support, not undermine.</p><h3 id="visualize-achievement" tabindex="-1">Visualize Achievement <a class="header-anchor" href="#visualize-achievement" aria-label="Permalink to &quot;Visualize Achievement&quot;">​</a></h3><p>Regularly imagine achieving your goals — the feeling, the moment.</p><h3 id="track-progress" tabindex="-1">Track Progress <a class="header-anchor" href="#track-progress" aria-label="Permalink to &quot;Track Progress&quot;">​</a></h3><p>What gets measured gets managed. Keep records.</p><h2 id="when-goals-aren-t-met" tabindex="-1">When Goals Aren&#39;t Met <a class="header-anchor" href="#when-goals-aren-t-met" aria-label="Permalink to &quot;When Goals Aren&#39;t Met&quot;">​</a></h2><p>Unmet goals aren&#39;t failures — they&#39;re data:</p><ol><li><strong>Analyze</strong>: Why wasn&#39;t it achieved?</li><li><strong>Learn</strong>: What does this teach you?</li><li><strong>Adjust</strong>: Modify the goal or approach</li><li><strong>Continue</strong>: Persistence beats perfection</li></ol><h2 id="the-mental-game-of-goals" tabindex="-1">The Mental Game of Goals <a class="header-anchor" href="#the-mental-game-of-goals" aria-label="Permalink to &quot;The Mental Game of Goals&quot;">​</a></h2><p>Goals affect psychology:</p><ul><li><strong>Too easy</strong>: Boredom, complacency</li><li><strong>Too hard</strong>: Anxiety, discouragement</li><li><strong>Just right</strong>: Engagement, flow, growth</li></ul><p>Find the sweet spot where goals challenge without overwhelming.</p><hr><p><em>Related: <a href="/en/education/goals/">Goal Setting Introduction</a> | <a href="/en/education/goals/smart-goals">SMART Goals</a> | <a href="/en/education/goals/planning">Planning Your Development</a></em></p>',88)])])}]]);export{l as __pageData,i as default};
